      "title": "康有為・梁啓超・譚嗣同の改革論",
      "body": [
        "こうして、<strong class=\"source-bold\"><ruby>公羊学<rt>くようがく</rt></ruby>派</strong>の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>康有為<rt>こうゆうい</rt></ruby></strong></span>や、彼のもとに集まった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>梁啓超<rt>りょうけいちょう</rt></ruby></strong></span>、<ruby>譚嗣同<rt>たんしどう</rt></ruby>らは、<strong class=\"source-bold\">日本の明治<ruby>維新<rt>いしん</rt></ruby>をモデルに、憲法制定や議会の開設</strong>による<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">立憲君主政</strong></span>の樹立を主張した。"
      ],
      "plainBody": [
        "こうして、公羊学派の康有為や、彼のもとに集まった梁啓超、譚嗣同らは、日本の明治維新をモデルに、憲法制定や議会の開設による立憲君主政の樹立を主張した。"
      ],
