      "id": "modern-c02-l10-p01-017",
      "title": "工場設置権と最恵国待遇",
      "body": [
        "しかも、当時の<strong class=\"source-bold\">欧米諸国はすでに帝国主義の段階</strong>に入っている。今までみたいに、製品を売る<ruby>市場<rt>しじょう</rt></ruby>にして、貿易で<ruby>儲<rt>もう</rt></ruby>けるだけの時代はもうおしまいだよ。だって、日清戦争で日本が清から「<strong class=\"source-bold\">工場設置権</strong>」を獲得したから、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>最恵国待遇<rt>さいけいこくたいぐう</rt></ruby></strong></span>を持っている<strong class=\"source-bold\">欧米諸国も中国に工場を建設できる</strong>。"
      ],
      "plainBody": [
        "しかも、当時の欧米諸国はすでに帝国主義の段階に入っている。今までみたいに、製品を売る市場にして、貿易で儲けるだけの時代はもうおしまいだよ。だって、日清戦争で日本が清から「工場設置権」を獲得したから、最恵国待遇を持っている欧米諸国も中国に工場を建設できる。"
      ],
