      "id": "modern-c02-l10-p01-024",
      "title": "イギリスの威海衛・新界と長江流域",
      "body": [
        "<strong class=\"source-bold\">イギリス</strong>は山東半島の先端にある清の海軍基地だった<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>威海衛<rt>いかいえい</rt></ruby></strong></span>を租借して、<strong class=\"source-bold\">ロシアとドイツに対抗</strong>し、さらに<ruby>香港<rt>ホンコン</rt></ruby>島対岸の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>九竜<rt>きゅうりゅう</rt></ruby>半島全域</strong></span>（<ruby>新界<rt>しんかい</rt></ruby>）を租借して、<strong class=\"source-bold\">イギリス領香港</strong>を完成させたんだよ。しかも、中国経済の中心だった<ruby>長江<rt>ちょうこう</rt></ruby>流域が勢力範囲だ。"
      ],
      "plainBody": [
        "イギリスは山東半島の先端にある清の海軍基地だった威海衛を租借して、ロシアとドイツに対抗し、さらに香港島対岸の九竜半島全域（新界）を租借して、イギリス領香港を完成させたんだよ。しかも、中国経済の中心だった長江流域が勢力範囲だ。"
      ],
