      "id": "modern-c02-l10-p01-028",
      "title": "太平洋の獲得地と航路",
      "body": [
        "でも米西戦争が終わると状況が変わったんだ。アメリカは<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">パリ条約</strong></span>で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">グアム、フィリピン</strong></span>を獲得し、さらに<strong class=\"source-bold\">米西戦争中に</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ハワイ</strong></span>も<ruby>併合<rt>へいごう</rt></ruby>したから、<strong class=\"source-bold\">ハワイ→グアム→フィリピン</strong>を結ぶと、<strong class=\"source-bold\">蒸気船による太平洋航路の完成</strong>だ。"
      ],
