        "でも米西戦争が終わると状況が変わったんだ。アメリカはパリ条約でグアム、フィリピンを獲得し、さらに米西戦争中にハワイも併合したから、ハワイ→グアム→フィリピンを結ぶと、蒸気船による太平洋航路の完成だ。"
