      "title": "ジョン＝ヘイの門戸開放宣言",
      "body": [
        "そこでアメリカは中国<ruby>市場<rt>しじょう</rt></ruby>への割り込みを狙い、国務長官の<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ジョン＝ヘイ</strong></span>は列強に対して「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>門戸開放<rt>もんこかいほう</rt></ruby>・機会均等</strong></span>」（この2つは1899年）を求め、さらに翌年に「<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>領土保全<rt>りょうどほぜん</rt></ruby></strong></span>」を提唱した。これが<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">門戸開放宣言</strong></span>だよ。"
      ],
      "plainBody": [
        "そこでアメリカは中国市場への割り込みを狙い、国務長官のジョン＝ヘイは列強に対して「門戸開放・機会均等」（この2つは1899年）を求め、さらに翌年に「領土保全」を提唱した。これが門戸開放宣言だよ。"
      ],
