      "title": "農民の保護と仇教運動",
      "body": [
        "彼らは小作人として農民を搾取していたんだけど、<strong class=\"source-bold\">困窮した農民たち</strong>は、「<ruby>飢<rt>う</rt></ruby>え<ruby>死<rt>じ</rt></ruby>にしそうです……助けてください……」って<strong class=\"source-bold\">教会に保護を求め</strong>、教会も彼らをかくまったから、旧来の<strong class=\"source-bold\">儒教的な価値観を守る郷紳もキリスト教への反感を強めた</strong>んだ。こうした反キリスト教運動をまとめて<strong class=\"source-bold\"><ruby>仇教<rt>きゅうきょう</rt></ruby>運動</strong>と呼ぶんだ。"
      ],
      "plainBody": [
        "彼らは小作人として農民を搾取していたんだけど、困窮した農民たちは、「飢え死にしそうです……助けてください……」って教会に保護を求め、教会も彼らをかくまったから、旧来の儒教的な価値観を守る郷紳もキリスト教への反感を強めたんだ。こうした反キリスト教運動をまとめて仇教運動と呼ぶんだ。"
      ],
