      "id": "modern-c02-l10-p02-011",
      "title": "西太后の宣戦と義和団戦争",
      "body": [
        "こうした動きを見た<strong class=\"source-bold\">清朝は完全に対応を間違えた</strong>……。「扶清滅洋」のスローガンにつられた保守派は、義和団を味方にして自分たちの権力維持に利用し、あわよくば列強を打倒できるかもしれない、って考えたんだろうね。考え方が甘いけどさ。そして、保守派の動きに乗って<strong class=\"source-bold\"><ruby>西太后<rt>せいたいこう</rt></ruby>は列強に<ruby>宣戦<rt>せんせん</rt></ruby>を<ruby>布告<rt>ふこく</rt></ruby></strong>しちゃった。こうして、ついに<strong class=\"source-bold\">列強 VS. 清朝の戦争</strong>である<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">義和団戦争</strong></span>になったんだよ。"
      ],
      "plainBody": [
        "こうした動きを見た清朝は完全に対応を間違えた……。「扶清滅洋」のスローガンにつられた保守派は、義和団を味方にして自分たちの権力維持に利用し、あわよくば列強を打倒できるかもしれない、って考えたんだろうね。考え方が甘いけどさ。そして、保守派の動きに乗って西太后は列強に宣戦を布告しちゃった。こうして、ついに列強 VS. 清朝の戦争である義和団戦争になったんだよ。"
      ],
