      "title": "8カ国共同出兵の構成",
      "body": [
        "宣戦布告されたら、列強も黙っているはずはない！ <strong class=\"source-bold\">義和団と清朝を打倒するため</strong>に<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">8カ国共同出兵</strong></span>をおこなったんだ。出兵した8カ国は<strong class=\"source-bold\">日本とロシアを中心に</strong>、イギリス・アメリカ・フランス・ドイツ・オーストリア・イタリアだよ。でもなんで日本とロシアの2国が中心になったんだろ？"
      ],
