      "id": "modern-c02-l10-p02-020",
      "title": "日本がロシアを警戒する",
      "body": [
        "ロシアがこのまま朝鮮まできたら、当時の日本じゃたぶん勝てない。それどころか、下手するとロシアが日本にまで<ruby>侵略<rt>しんりゃく</rt></ruby>の手を伸ばしてくるかもしれない……「今のうちになんとかしておかなきゃマズい」って、<strong class=\"source-bold\">日本はロシアを警戒</strong>していたんだ。"
      ],
