      "id": "modern-c02-l10-p02-029",
      "title": "奉天会戦と日本海海戦",
      "body": [
        "その後、陸軍は満洲に進撃して<strong class=\"source-bold\"><ruby>奉天<rt>ほうてん</rt></ruby>会戦</strong>でロシア軍と衝突したけど、これも厳しい！ でも、ロシアの作戦ミスに助けられて、なんとか勝利した。一方の海軍では、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">日本海海戦</strong></span>で<strong class=\"source-bold\">ロシアのバルチック艦隊を壊滅</strong>させて、海軍史上に残る大勝利を収めたんだ。"
      ],
