      "id": "modern-c02-l10-p02-031",
      "title": "血の日曜日事件とロシア革命",
      "body": [
        "一方の<strong class=\"source-bold\">ロシア</strong>も、日露戦争中に食糧不足となった首都<strong class=\"source-bold\">ペテルブルク</strong>で、皇帝<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ニコライ2世</strong></span>に対して戦争停止とツァーリズムの廃止を求める<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">血の日曜日事件</strong></span>が起こり、<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">第1次ロシア革命【1905年革命】</strong></span>に発展した。"
      ],
