      "title": "ローズヴェルトの仲介と全権代表",
      "body": [
        "1905年9月、<strong class=\"source-bold\">アメリカ大統領</strong><span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">セオドア＝ローズヴェルト</strong></span>の仲介で<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\">ポーツマス条約</strong></span>が結ばれ、<strong class=\"source-bold\">日露戦争は終結</strong>したよ（日本側全権は<strong class=\"source-bold\"><ruby>小村寿太郎<rt>こむらじゅたろう</rt></ruby></strong>、ロシア側全権は<strong class=\"source-bold\">ウィッテ</strong>）。"
      ],
      "plainBody": [
        "1905年9月、アメリカ大統領セオドア＝ローズヴェルトの仲介でポーツマス条約が結ばれ、日露戦争は終結したよ（日本側全権は小村寿太郎、ロシア側全権はウィッテ）。"
      ],
