      "body": [
        "そして、国会開設を終えた1894年、<strong class=\"source-bold\">日英通商航海条約</strong>が結ばれて<strong class=\"source-bold\">領事裁判権の<ruby>撤廃<rt>てっぱい</rt></ruby></strong>に成功したんだ。その後、各国も改正に応じ、さらに日露戦争後の1911年には<strong class=\"source-bold\">関税自主権も全面的に認められた</strong>んだよ。"
      ],
