      "body": [
        "<strong class=\"source-bold\">日露戦争中</strong>の日本では、ナショナリズムが高まって戦争を支持する人が多かったけど、<strong class=\"source-bold\"><ruby>幸徳秋水<rt>こうとくしゅうすい</rt></ruby></strong>など<strong class=\"source-bold\">社会主義者は戦争に反対</strong>した。"
      ],
