      "id": "modern-c02-l10-p03-004",
      "title": "反日感情と大韓帝国",
      "body": [
        "しかし、かえって反日感情を強め、<strong class=\"source-bold\">朝鮮内部では親露派が勢力を拡大</strong>してしまった。さらに、朝鮮は清の<ruby>属国<rt>ぞっこく</rt></ruby>ではなくなったことを示すために、国号を<span data-source-color=\"red\" style=\"color:#e52715\"><strong class=\"source-red-bold\"><ruby>大韓<rt>だいかん</rt></ruby>帝国</strong></span>と改称したよ（この時代の「韓国」という表記は「大韓帝国」の省略だよ）。"
      ],
