        "しかし、かえって反日感情を強め、朝鮮内部では親露派が勢力を拡大してしまった。さらに、朝鮮は清の属国ではなくなったことを示すために、国号を大韓帝国と改称したよ（この時代の「韓国」という表記は「大韓帝国」の省略だよ）。"
