      "id": "modern-c02-l10-p04-008",
      "title": "革命派の清朝打倒と増税反発",
      "body": [
        "ただ、<strong class=\"source-bold\">この改革はもはや手遅れ</strong>だよ。だって、<ruby>義和団<rt>ぎわだん</rt></ruby>戦争での<ruby>清<rt>シン</rt></ruby>朝の対応に失望して、<strong class=\"source-bold\">革命派はすでに清朝打倒を目標に掲げている</strong>んだもん。さらに、清朝内部では<ruby>光緒<rt>こうしょ</rt></ruby>新政をおこなうための財源を増税に頼ったから、各地で清朝への反発が強まった。"
      ],
      "plainBody": [
        "ただ、この改革はもはや手遅れだよ。だって、義和団戦争での清朝の対応に失望して、革命派はすでに清朝打倒を目標に掲げているんだもん。さらに、清朝内部では光緒新政をおこなうための財源を増税に頼ったから、各地で清朝への反発が強まった。"
      ],
