      "id": "modern-c02-l10-p04-015",
      "title": "黄興の華興会と蔡元培の光復会",
      "body": [
        "そして20世紀に入ると、<strong class=\"source-bold\"><ruby>湖南<rt>こなん</rt></ruby>派</strong>（湖南省出身）の<ruby>黄興<rt>こうこう</rt></ruby>を会長とする<strong class=\"source-bold\"><ruby>華<rt>か</rt></ruby><ruby>興会<rt>こうかい</rt></ruby></strong>、<strong class=\"source-bold\"><ruby>浙江<rt>せっこう</rt></ruby>派</strong>（浙江省出身）の<ruby>蔡元培<rt>さいげんばい</rt></ruby>を会長とする<strong class=\"source-bold\"><ruby>光復<rt>こうふく</rt></ruby>会</strong>などの革命団体が結成されたけど、これらはすべて<strong class=\"source-bold\">同じ出身地</strong>の人が集まった団体だよ。"
      ],
