      "title": "幹線鉄道国有化を決める",
      "body": [
        "そこで、外国資本を導入することにしたんだけど、すでに民間資本が自前で建設したり<ruby>列強<rt>れっきょう</rt></ruby>から買い戻したりした鉄道もある。そこで清朝政府は「<strong class=\"source-bold\">民族資本家たちが建設している幹線鉄道を取り上げて国有にして、外国資本を導入して建設しよう</strong>」って決めたんだ。"
      ],
