      "body": [
        "この時に国有化された<ruby>粤漢<rt>エツカン</rt></ruby>鉄道（<ruby>漢口<rt>かんこう</rt></ruby>〜<ruby>広州<rt>こうしゅう</rt></ruby>）は利権回収運動で列強から買い戻し、<ruby>川漢<rt>せんかん</rt></ruby>鉄道（四川〜漢口）は民族資本家がお金を出しあって建設した鉄道だ。せっかく列強から買い戻した鉄道に外資を導入してどうすんだよ。"
      ],
