      "title": "湖北新軍が鎮圧を拒否",
      "body": [
        "清朝は、<strong class=\"source-bold\">湖北新軍</strong>（湖北省につくられた新軍）に<ruby>鎮圧<rt>ちんあつ</rt></ruby>を命令したんだけど……彼らも怒り始めた。「オレの親父も金出してんだよ」ってね。だって、<strong class=\"source-bold\">新軍のなかには民族資本家の息子もいた</strong>よね。そしてついに、<strong class=\"source-bold\">湖北新軍のなかの革命派が四川暴動の鎮圧を拒否</strong>して反乱を起こした。"
      ],
      "plainBody": [
        "清朝は、湖北新軍（湖北省につくられた新軍）に鎮圧を命令したんだけど……彼らも怒り始めた。「オレの親父も金出してんだよ」ってね。だって、新軍のなかには民族資本家の息子もいたよね。そしてついに、湖北新軍のなかの革命派が四川暴動の鎮圧を拒否して反乱を起こした。"
      ],
