      "id": "modern-c02-l10-p04-033",
      "title": "革命派が袁世凱との取引を選ぶ",
      "body": [
        "この時、袁世凱は「もはや清朝はもたないな」と思っていたし、列強も袁世凱を改革派だと思って支持していたから、革命派のなかには「清朝を滅ぼすために、袁世凱を味方にしたほうがいいんじゃないか？」と考える人が増えてたんだよ。"
      ],
